.os-scrollbar-vertical:hover .os-scrollbar-handle { width: var(--os-handle-perpendicular-size-hover); }
.os-scrollbar-vertical:active .os-scrollbar-handle { width: var(--os-handle-perpendicular-size-active); }
[data-overlayscrollbars-viewport~="measuring"] > .os-scrollbar, .os-theme-none.os-scrollbar { display: none !important; }
.os-theme-dark, .os-theme-light { box-sizing: border-box; --os-size: 10px; --os-padding-perpendicular: 2px; --os-padding-axis: 2px; --os-track-border-radius: 10px; --os-handle-interactive-area-offset: 4px; --os-handle-border-radius: 10px; }
.os-theme-dark { --os-handle-bg: rgba(0, 0, 0, 0.44); --os-handle-bg-hover: rgba(0, 0, 0, 0.55); --os-handle-bg-active: rgba(0, 0, 0, 0.66); }
.os-theme-light { --os-handle-bg: rgba(255, 255, 255, 0.44); --os-handle-bg-hover: rgba(255, 255, 255, 0.55); --os-handle-bg-active: rgba(255, 255, 255, 0.66); }
